const ROOT = process.cwd(); const DATA = process.env.STOCKPILOT_DATA_DIR || join(ROOT, 'data'); mkdirSync(DATA, {recursive:true});
const db = new DatabaseSync(join(DATA,'stockpilot.sqlite')); db.exec('PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL;');
db.exec(`
CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'PKR',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS memberships(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL,UNIQUE(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),tenant_id TEXT NOT NULL REFERENCES tenants(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS warehouses(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),code TEXT NOT NULL,name TEXT NOT NULL,city TEXT NOT NULL DEFAULT '',capacity REAL NOT NULL DEFAULT 0,UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS locations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),warehouse_id TEXT NOT NULL REFERENCES warehouses(id),parent_id TEXT,code TEXT NOT NULL,name TEXT NOT NULL,kind TEXT NOT NULL,capacity REAL NOT NULL DEFAULT 0,barcode TEXT,UNIQUE(tenant_id,warehouse_id,code));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),sku TEXT NOT NULL,name TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'General',barcode TEXT,cost REAL NOT NULL DEFAULT 0,price REAL NOT NULL DEFAULT 0,reorder REAL NOT NULL DEFAULT 0,uom TEXT NOT NULL DEFAULT 'ea',UNIQUE(tenant_id,sku));
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',credit_limit REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS suppliers(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS balances(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),warehouse_id TEXT NOT NULL REFERENCES warehouses(id),location_id TEXT NOT NULL REFERENCES locations(id),product_id TEXT NOT NULL REFERENCES products(id),owner TEXT NOT NULL DEFAULT 'company',lot TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'available',qty REAL NOT NULL DEFAULT 0 CHECK(qty>=0),UNIQUE(tenant_id,warehouse_id,location_id,product_id,owner,lot,status));
CREATE TABLE IF NOT EXISTS lot_metadata(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,product_id TEXT NOT NULL,lot TEXT NOT NULL,expiry_date TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,product_id,lot));
CREATE TABLE IF NOT EXISTS movements(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,product_id TEXT NOT NULL,warehouse_id TEXT NOT NULL,location_id TEXT NOT NULL,kind TEXT NOT NULL,delta REAL NOT NULL,ref TEXT,note TEXT,actor TEXT NOT NULL,owner TEXT NOT NULL DEFAULT 'company',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS receipts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,supplier_id TEXT,warehouse_id TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS receipt_lines(id TEXT PRIMARY KEY,receipt_id TEXT NOT NULL,product_id TEXT NOT NULL,location_id TEXT NOT NULL,qty REAL NOT NULL,lot TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS purchase_orders(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,supplier_id TEXT NOT NULL,warehouse_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',total REAL NOT NULL DEFAULT 0,expected_at TEXT,created_by TEXT NOT NULL,approved_by TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchase_order_lines(id TEXT PRIMARY KEY,order_id TEXT NOT NULL,product_id TEXT NOT NULL,qty REAL NOT NULL,cost REAL NOT NULL,received_qty REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS stock_counts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,warehouse_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending_approval',created_by TEXT NOT NULL,approved_by TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stock_count_lines(id TEXT PRIMARY KEY,count_id TEXT NOT NULL,product_id TEXT NOT NULL,location_id TEXT NOT NULL,expected REAL NOT NULL,counted REAL NOT NULL,variance REAL NOT NULL);
CREATE TABLE IF NOT EXISTS returns(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,order_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'completed',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS return_lines(id TEXT PRIMARY KEY,return_id TEXT NOT NULL,product_id TEXT NOT NULL,location_id TEXT NOT NULL,qty REAL NOT NULL,disposition TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS expenses(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,warehouse_id TEXT,category TEXT NOT NULL,amount REAL NOT NULL,currency TEXT NOT NULL DEFAULT 'PKR',memo TEXT NOT NULL DEFAULT '',spent_at TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS storage_rates(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,customer_id TEXT NOT NULL,basis TEXT NOT NULL,rate REAL NOT NULL,currency TEXT NOT NULL DEFAULT 'PKR',active INTEGER NOT NULL DEFAULT 1,UNIQUE(tenant_id,customer_id,basis));
CREATE TABLE IF NOT EXISTS storage_invoices(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,customer_id TEXT NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,quantity REAL NOT NULL,rate REAL NOT NULL,amount REAL NOT NULL,currency TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,customer_id,period_start,period_end));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,customer_id TEXT NOT NULL,warehouse_id TEXT NOT NULL,status TEXT NOT NULL,total REAL NOT NULL DEFAULT 0,package_count INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_lines(id TEXT PRIMARY KEY,order_id TEXT NOT NULL,product_id TEXT NOT NULL,qty REAL NOT NULL,price REAL NOT NULL,picked REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sales_invoices(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,customer_id TEXT NOT NULL,order_id TEXT NOT NULL UNIQUE,invoice_number TEXT NOT NULL,total REAL NOT NULL,paid REAL NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'open',due_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,invoice_number));
CREATE TABLE IF NOT EXISTS supplier_bills(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,supplier_id TEXT NOT NULL,purchase_order_id TEXT NOT NULL UNIQUE,bill_number TEXT NOT NULL,total REAL NOT NULL,paid REAL NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'open',due_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,bill_number));
CREATE TABLE IF NOT EXISTS financial_payments(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,document_type TEXT NOT NULL CHECK(document_type IN ('sales_invoice','supplier_bill')),document_id TEXT NOT NULL,amount REAL NOT NULL CHECK(amount>0),reference TEXT NOT NULL DEFAULT '',memo TEXT NOT NULL DEFAULT '',paid_at TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS received_goods_supplier_bill AFTER UPDATE OF received_qty ON purchase_order_lines WHEN NEW.received_qty>0 BEGIN INSERT INTO supplier_bills(id,tenant_id,supplier_id,purchase_order_id,bill_number,total,due_at) VALUES(lower(hex(randomblob(16))),(SELECT tenant_id FROM purchase_orders WHERE id=NEW.order_id),(SELECT supplier_id FROM purchase_orders WHERE id=NEW.order_id),NEW.order_id,'BILL-'||upper(substr(NEW.order_id,1,8)),(SELECT COALESCE(SUM(received_qty*cost),0) FROM purchase_order_lines WHERE order_id=NEW.order_id),date('now','+30 day')) ON CONFLICT(purchase_order_id) DO UPDATE SET total=excluded.total; END;
CREATE TABLE IF NOT EXISTS transfers(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,product_id TEXT NOT NULL,from_warehouse TEXT NOT NULL,to_warehouse TEXT NOT NULL,from_location TEXT NOT NULL,to_location TEXT NOT NULL,qty REAL NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shipments(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,order_id TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'dispatched',carrier TEXT NOT NULL DEFAULT '',tracking_number TEXT NOT NULL DEFAULT '',vehicle TEXT NOT NULL DEFAULT '',driver TEXT NOT NULL DEFAULT '',destination TEXT NOT NULL DEFAULT '',package_count INTEGER NOT NULL DEFAULT 1,dispatched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS order_dispatch_shipment AFTER UPDATE OF status ON orders WHEN NEW.status='dispatched' BEGIN INSERT OR IGNORE INTO shipments(id,tenant_id,order_id,status,package_count) VALUES(lower(hex(randomblob(16))),NEW.tenant_id,NEW.id,'dispatched',NEW.package_count); END;
CREATE TRIGGER IF NOT EXISTS order_dispatch_invoice AFTER UPDATE OF status ON orders WHEN NEW.status='dispatched' BEGIN INSERT OR IGNORE INTO sales_invoices(id,tenant_id,customer_id,order_id,invoice_number,total,due_at) VALUES(lower(hex(randomblob(16))),NEW.tenant_id,NEW.customer_id,NEW.id,'INV-'||upper(substr(NEW.id,1,8)),NEW.total,date('now','+30 day')); END;
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS balances_product_idx ON balances(tenant_id,product_id,status);
CREATE INDEX IF NOT EXISTS movement_time_idx ON movements(tenant_id,created_at DESC);
`);
const uid=()=>randomBytes(16).toString('hex'); const hashPassword=(p,s=randomBytes(16).toString('hex'))=>`${s}:${scryptSync(p,s,64).toString('hex')}`;
function verify(p,h){const [s,hex]=h.split(':');const a=scryptSync(p,s,64),b=Buffer.from(hex,'hex');return a.length===b.length&&timingSafeEqual(a,b)}
const companyStockSql=sql=>sql.replace(/product_id=\? AND status='available'/g,"product_id=? AND owner='company' AND status='available'").replace(/(FROM balances(?: b)? WHERE tenant_id=\?) AND status='available'/g,"$1 AND owner='company' AND status='available'").replace(/(b\.tenant_id=p\.tenant_id) AND b\.status='available'/g,"$1 AND b.owner='company' AND b.status='available'");
const q=(sql,...args)=>db.prepare(companyStockSql(sql)).all(...args), one=(sql,...args)=>db.prepare(companyStockSql(sql)).get(...args), run=(sql,...args)=>db.prepare(sql).run(...args);
const roles={owner:['*'],manager:['dashboard.read','inventory.read','inventory.adjust','warehouse.read','warehouse.manage','product.read','product.manage','receiving.manage','orders.manage','transfer.manage','purchasing.manage','report.read','people.read','supplier.manage'],controller:['dashboard.read','inventory.read','inventory.adjust','product.read','warehouse.read','transfer.manage','report.read'],operator:['inventory.read','receiving.execute','orders.execute','transfer.execute'],sales:['dashboard.read','product.read','inventory.read','orders.manage','customer.manage','people.read'],purchase:['product.read','inventory.read','receiving.manage','supplier.manage','purchasing.manage'],accountant:['dashboard.read','report.read','finance.read','finance.manage'],auditor:['dashboard.read','inventory.read','report.read','audit.read']};
const permissions=(role,p)=>roles[role]?.includes('*')||roles[role]?.includes(p);
function seed(){if(one('SELECT id FROM tenants LIMIT 1'))return;const t=uid(),u=uid(),w=uid(),l=uid();run('INSERT INTO tenants(id,name) VALUES(?,?)',t,'Atlas Trading Co.');run('INSERT INTO users(id,email,name,password_hash) VALUES(?,?,?,?)',u,'owner@example.com','Ahmed Khan',hashPassword('StockpilotDemo2026!'));run('INSERT INTO memberships(id,tenant_id,user_id,role) VALUES(?,?,?,?)',uid(),t,u,'owner');run('INSERT INTO warehouses(id,tenant_id,code,name,city,capacity) VALUES(?,?,?,?,?,?)',w,t,'KHI-01','Karachi Main Warehouse','Karachi',1200);run('INSERT INTO locations(id,tenant_id,warehouse_id,code,name,kind,capacity,barcode) VALUES(?,?,?,?,?,?,?,?)',l,t,w,'A-01-R01-B01','Zone A · Rack 01 · Bin 01','bin',100,'LOC-A01-R01-B01');const data=[['EL-1001','Wireless Mouse','Electronics',750,1490,12],['EL-1002','USB-C Hub 7-in-1','Electronics',4300,6900,8],['TX-2040','Cotton Bedsheet Set','Textiles',2200,3750,10],['FD-0301','Premium Basmati Rice 5kg','Food',1100,1650,20],['GN-6002','Stainless Steel Flask','General',850,1450,8],['EL-1020','Bluetooth Speaker','Electronics',1850,2990,10],['TX-2090','Bath Towel Pair','Textiles',780,1350,14],['GN-6021','LED Desk Lamp','General',1450,2390,6]];for(const [sku,name,cat,cost,price,reorder] of data){const p=uid();run('INSERT INTO products(id,tenant_id,sku,name,category,barcode,cost,price,reorder) VALUES(?,?,?,?,?,?,?,?,?)',p,t,sku,name,cat,sku,cost,price,reorder);const b=uid(),qty=Math.floor(8+Math.random()*90);run('INSERT INTO balances(id,tenant_id,warehouse_id,location_id,product_id,qty) VALUES(?,?,?,?,?,?)',b,t,w,l,p,qty);run('INSERT INTO movements(id,tenant_id,product_id,warehouse_id,location_id,kind,delta,ref,note,actor) VALUES(?,?,?,?,?,?,?,?,?,?)',uid(),t,p,w,l,'opening_balance',qty,'SEED','Development sample stock',u)}for(const n of ['Metro Cash & Carry','Al Noor Stores','City Mart','Faisal Traders','United General Store'])run('INSERT INTO customers(id,tenant_id,name,phone,email,credit_limit) VALUES(?,?,?,?,?,?)',uid(),t,n,'+92 300 0000000','',500000);for(const n of ['Samsung Electronics','Pak Textile Mills','National Foods','Universal Traders'])run('INSERT INTO suppliers(id,tenant_id,name) VALUES(?,?,?)',uid(),t,n)}
seed();
